from pathlib import Path
from html.parser import HTMLParser
import re
class Visible(HTMLParser):
 def __init__(self):
  super().__init__(); self.hidden=0; self.text=[]
 def handle_starttag(self, tag, attrs):
  if tag in ('script','style'): self.hidden+=1
 def handle_endtag(self, tag):
  if tag in ('script','style'): self.hidden=max(0,self.hidden-1)
 def handle_data(self, data):
  if not self.hidden: self.text.append(data)
p=Visible()
p.feed(Path('products/distribution/sqlite-lemonsqueezy-fit/raw/fees.html').read_text())
s=' '.join(' '.join(p.text).split())
for m in list(re.finditer(r'5\s*%|50\s*¢|0\.50|payout fees',s,re.I))[:16]:
 print(s[max(0,m.start()-65):m.end()+75])
